                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var saved = context.Instructors.Include(i => i.OfficeAssignment).First();
            Assert.Equal("Room 101", saved.OfficeAssignment!.Location);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedFull(context);

            var ca = context.CourseAssignments.First();
            Assert.Equal(1050, ca.CourseID);
            Assert.Equal(10, ca.InstructorID);
        }

        [Fact]
        public void CanQueryStudents_WithEnrollments()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedFull(context);

            var student = context.Students
                .Include(s => s.Enrollments)
                .First(s => s.ID == 1);

            Assert.NotEmpty(student.Enrollments);
        }

        [Fact]
        public void CanDeleteStudent()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedStudents(context);

            var student = context.Students.First();
            context.Students.Remove(student);
            context.SaveChanges();

            Assert.Equal(2, context.Students.Count());
        }

        [Fact]
        public void NotificationDbSet_Exists()
        {
            using var context = TestHelper.CreateContext();
            var notification = new Notification
            {
                EntityType = "Test",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "Test",
                IsRead = false
            };
            context.Notifications.Add(notification);
            context.SaveChanges();

            Assert.Single(context.Notifications);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsDatabase()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.True(context.Students.Any());
            Assert.True(context.Instructors.Any());
            Assert.True(context.Departments.Any());
            Assert.True(context.Courses.Any());
            Assert.True(context.Enrollments.Any());
            Assert.True(context.OfficeAssignments.Any());
            Assert.True(context.CourseAssignments.Any());
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicate()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            DbInitializer.Initialize(context);
            Assert.Equal(studentCount, context.Students.Count());
        }

        [Fact]
        public void Initialize_Seeds8Students()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(8, context.Students.Count());
        }

        [Fact]
        public void Initialize_Seeds5Instructors()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(5, context.Instructors.Count());
        }

        [Fact]
        public void Initialize_Seeds4Departments()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_Seeds7Courses()
        {
