using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanCreateDatabaseAndAddStudent()
        {
            using var context = TestHelper.CreateContext();
            context.Students.Add(new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            });
            context.SaveChanges();

            Assert.Single(context.Students);
        }

        [Fact]
        public void CanAddCourseWithDepartment()
        {
            using var context = TestHelper.CreateContext();
            var dept = new Department
            {
                Name = "Engineering",
                Budget = 100000,
                StartDate = DateTime.Parse("2020-01-01")
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            context.Courses.Add(new Course
            {
                CourseID = 101,
                Title = "Physics",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            });
            context.SaveChanges();

            Assert.Single(context.Courses);
            Assert.Equal("Physics", context.Courses.First().Title);
        }

        [Fact]
        public void CanAddEnrollment_WithStudentAndCourse()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedCourses(context);
            TestHelper.SeedStudents(context);

            context.Enrollments.Add(new Enrollment
            {
                StudentID = 1,
                CourseID = 1050,
                Grade = Grade.A
            });
            context.SaveChanges();

            Assert.Single(context.Enrollments);
            var enrollment = context.Enrollments.First();
            Assert.Equal(Grade.A, enrollment.Grade);
        }

        [Fact]
        public void CanAddInstructorWithOfficeAssignment()
        {
            using var context = TestHelper.CreateContext();
            var instructor = new Instructor
            {
                FirstMidName = "John",
                LastName = "Smith",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { Location = "Room 101" }
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var saved = context.Instructors.Include(i => i.OfficeAssignment).First();
            Assert.Equal("Room 101", saved.OfficeAssignment!.Location);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedFull(context);

            var ca = context.CourseAssignments.First();
            Assert.Equal(1050, ca.CourseID);
            Assert.Equal(10, ca.InstructorID);
        }

        [Fact]
        public void CanQueryStudents_WithEnrollments()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedFull(context);

            var student = context.Students
                .Include(s => s.Enrollments)
                .First(s => s.ID == 1);

            Assert.NotEmpty(student.Enrollments);
        }

        [Fact]
        public void CanDeleteStudent()
        {
            using var context = TestHelper.CreateContext();
            TestHelper.SeedStudents(context);

            var student = context.Students.First();
            context.Students.Remove(student);
            context.SaveChanges();

            Assert.Equal(2, context.Students.Count());
        }

        [Fact]
        public void NotificationDbSet_Exists()
        {
            using var context = TestHelper.CreateContext();
            var notification = new Notification
            {
                EntityType = "Test",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = DateTime.Now,
                CreatedBy = "Test",
                IsRead = false
            };
            context.Notifications.Add(notification);
            context.SaveChanges();

            Assert.Single(context.Notifications);
        }
    }

    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_SeedsDatabase()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);

            Assert.True(context.Students.Any());
            Assert.True(context.Instructors.Any());
            Assert.True(context.Departments.Any());
            Assert.True(context.Courses.Any());
            Assert.True(context.Enrollments.Any());
            Assert.True(context.OfficeAssignments.Any());
            Assert.True(context.CourseAssignments.Any());
        }

        [Fact]
        public void Initialize_CalledTwice_DoesNotDuplicate()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();

            DbInitializer.Initialize(context);
            Assert.Equal(studentCount, context.Students.Count());
        }

        [Fact]
        public void Initialize_Seeds8Students()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(8, context.Students.Count());
        }

        [Fact]
        public void Initialize_Seeds5Instructors()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(5, context.Instructors.Count());
        }

        [Fact]
        public void Initialize_Seeds4Departments()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(4, context.Departments.Count());
        }

        [Fact]
        public void Initialize_Seeds7Courses()
        {
            using var context = TestHelper.CreateContext();
            DbInitializer.Initialize(context);
            Assert.Equal(7, context.Courses.Count());
        }
    }

    public class SchoolContextFactoryTests
    {
        [Fact]
        public void Create_WithValidConfig_ReturnsContext()
        {
            var config = new Microsoft.Extensions.Configuration.ConfigurationBuilder()
                .AddInMemoryCollection(new System.Collections.Generic.Dictionary<string, string?>
                {
                    { "ConnectionStrings:DefaultConnection", "Server=localhost;Database=Test;Trusted_Connection=True;" }
