using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student { FirstMidName = "John", LastName = "Doe" };
            Assert.Equal("Doe, John", student.FullName);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void EnrollmentDate_CanBeSet()
        {
            var date = DateTime.Parse("2023-09-01");
            var student = new Student { EnrollmentDate = date };
            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Enrollments_CanBeInitialized()
        {
            var student = new Student
            {
                Enrollments = new List<Enrollment> { new Enrollment() }
            };
            Assert.Single(student.Enrollments);
        }
    }

    public class InstructorTests
    {
        [Fact]
        public void HireDate_CanBeSet()
        {
            var date = DateTime.Parse("2020-01-15");
            var instructor = new Instructor { HireDate = date };
            Assert.Equal(date, instructor.HireDate);
        }

        [Fact]
        public void CourseAssignments_CanBeInitialized()
        {
            var instructor = new Instructor
            {
                CourseAssignments = new List<CourseAssignment> { new CourseAssignment() }
            };
            Assert.Single(instructor.CourseAssignments);
        }

        [Fact]
        public void OfficeAssignment_CanBeSet()
        {
            var instructor = new Instructor
            {
                OfficeAssignment = new OfficeAssignment { Location = "Room 1" }
            };
            Assert.Equal("Room 1", instructor.OfficeAssignment.Location);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_PropertiesCanBeSet()
        {
            var course = new Course
            {
                CourseID = 101,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/images/test.jpg"
            };

            Assert.Equal(101, course.CourseID);
            Assert.Equal("Test Course", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/images/test.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_NavigationProperties_CanBeSet()
        {
            var course = new Course
            {
                Department = new Department { Name = "Dept" },
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };

            Assert.NotNull(course.Department);
            Assert.NotNull(course.Enrollments);
            Assert.NotNull(course.CourseAssignments);
        }
    }

    public class DepartmentTests
    {
        [Fact]
        public void Department_PropertiesCanBeSet()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Test",
                Budget = 50000m,
                StartDate = DateTime.Parse("2020-01-01"),
                InstructorID = 5,
                RowVersion = new byte[] { 1, 2, 3 }
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Test", dept.Name);
            Assert.Equal(50000m, dept.Budget);
            Assert.Equal(5, dept.InstructorID);
            Assert.Equal(new byte[] { 1, 2, 3 }, dept.RowVersion);
        }

        [Fact]
        public void Department_InstructorIDNullable()
        {
            var dept = new Department { InstructorID = null };
            Assert.Null(dept.InstructorID);
        }
    }

    public class EnrollmentTests
    {
        [Fact]
        public void Enrollment_GradeNullable()
        {
            var enrollment = new Enrollment { Grade = null };
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Enrollment_GradeCanBeSet()
        {
            var enrollment = new Enrollment { Grade = Grade.A };
            Assert.Equal(Grade.A, enrollment.Grade);
        }

        [Fact]
        public void Grade_HasExpectedValues()
        {
            Assert.Equal(0, (int)Grade.A);
            Assert.Equal(1, (int)Grade.B);
            Assert.Equal(2, (int)Grade.C);
            Assert.Equal(3, (int)Grade.D);
            Assert.Equal(4, (int)Grade.F);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_PropertiesCanBeSet()
        {
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Test",
                CreatedAt = now,
                CreatedBy = "admin",
                IsRead = false,
                ReadAt = null
            };

            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Test", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_TrueWhenRequestIdIsSet()
        {
            var model = new ErrorViewModel { RequestId = "123" };
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_FalseWhenRequestIdIsNull()
        {
            var model = new ErrorViewModel { RequestId = null };
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_FalseWhenRequestIdIsEmpty()
        {
            var model = new ErrorViewModel { RequestId = "" };
            Assert.False(model.ShowRequestId);
        }
    }

    public class ViewModelTests
    {
        [Fact]
        public void AssignedCourseData_PropertiesCanBeSet()
        {
            var data = new AssignedCourseData
            {
                CourseID = 1,
                Title = "Test",
                Assigned = true
            };

            Assert.Equal(1, data.CourseID);
            Assert.Equal("Test", data.Title);
            Assert.True(data.Assigned);
        }

        [Fact]
        public void EnrollmentDateGroup_PropertiesCanBeSet()
        {
            var group = new EnrollmentDateGroup
            {
                EnrollmentDate = DateTime.Parse("2023-01-01"),
                StudentCount = 5
            };

            Assert.Equal(2023, group.EnrollmentDate!.Value.Year);
            Assert.Equal(5, group.StudentCount);
        }

        [Fact]
        public void EnrollmentDateGroup_NullableDate()
        {
            var group = new EnrollmentDateGroup { EnrollmentDate = null };
            Assert.Null(group.EnrollmentDate);
        }

        [Fact]
        public void InstructorIndexData_PropertiesCanBeSet()
        {
            var data = new InstructorIndexData
            {
                Instructors = new List<Instructor>(),
                Courses = new List<Course>(),
                Enrollments = new List<Enrollment>()
            };

            Assert.NotNull(data.Instructors);
            Assert.NotNull(data.Courses);
            Assert.NotNull(data.Enrollments);
        }
    }

    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsPaginatedList()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_FalseForFirstPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(items, 1, 10);
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_TrueForSecondPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(items, 2, 10);
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_TrueForFirstPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(items, 1, 10);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FalseForLastPage()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(items, 3, 10);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_LastPage_ContainsRemainingItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();
            var result = PaginatedList<int>.Create(items, 3, 10);
            Assert.Equal(5, result.Count);
        }

        [Fact]
        public void Constructor_SetsProperties()
        {
            var list = new PaginatedList<string>(new List<string> { "a", "b" }, 10, 2, 3);
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
            Assert.Equal(2, list.Count);
        }
    }
}

