public class SchoolContextFactoryTests
{
    [Fact]
    public void Create_WithValidConfig_ReturnsContext()
    {
        // Use a mock configuration
        var mockConfig = new Moq.Mock<Microsoft.Extensions.Configuration.IConfiguration>();
        var mockSection = new Moq.Mock<Microsoft.Extensions.Configuration.IConfigurationSection>();
        mockSection.Setup(s => s.Value).Returns("Server=localhost;Database=Test;Trusted_Connection=True;");
        mockConfig.Setup(c => c.GetSection("ConnectionStrings:DefaultConnection")).Returns(mockSection.Object);

        // SchoolContextFactory.Create reads config.GetConnectionString("DefaultConnection")
        // which calls config.GetSection("ConnectionStrings")["DefaultConnection"]
        var connStrSection = new Moq.Mock<Microsoft.Extensions.Configuration.IConfigurationSection>();
        connStrSection.Setup(s => s[It.IsAny<string>()]).Returns("Server=localhost;Database=Test;Trusted_Connection=True;");
        mockConfig.Setup(c => c.GetSection("ConnectionStrings")).Returns(connStrSection.Object);

        var context = SchoolContextFactory.Create(mockConfig.Object);
        Assert.NotNull(context);
        context.Dispose();
    }
}

